const fs = require('fs');
const sigPath = '/memory/email_signals.json';
let store = { signals: [], pending: {} };
try { store = JSON.parse(fs.readFileSync(sigPath, 'utf8')); } catch(e) {}

const sd = $getWorkflowStaticData('global');
const lastCheck = sd.lastCheck || new Date(Date.now() - 15*60*1000).toISOString();
sd.lastCheck = new Date().toISOString();

return [{ json: { lastCheck, signals: store.signals, pending: store.pending || {} } }];

function parseRawObservation(text) {
  var blocks = text.split(/\n\s*\n/).map(function(b) { return b.trim(); }).filter(Boolean);
  var out = [];
  for (var i = 0; i < blocks.length; i++) {
    var block = blocks[i];
    var idM = block.match(/^ID:\s*(\S+)/m);
    var subjM = block.match(/^Subject:\s*(.*)$/m);
    var fromM = block.match(/^From:\s*(.*)$/m);
    var dateM = block.match(/^Date:\s*(.*)$/m);
    if (!idM) continue;
    var fromName = '', fromEmail = '';
    if (fromM) {
      var m = fromM[1].match(/^(.*?)<(.+)>\s*$/);
      if (m) { fromName = m[1].trim(); fromEmail = m[2].trim(); }
      else { fromEmail = fromM[1].trim(); }
    }
    out.push({
      id: idM[1],
      from_name: fromName,
      from_email: fromEmail,
      subject: subjM ? subjM[1].trim() : '',
      date: dateM ? dateM[1].trim() : '',
      snippet: ''
    });
  }
  return out;
}

var first = $input.first().json;
var emails = [];
var source = 'none';

// Prefer the Gmail MCP tool's own raw text (deterministic) over the agent's
// JSON reformatting of it. The agent has been observed to fabricate subject/from
// fields for real messages when re-typing them as JSON (2026-07-08: msg
// 19f3a6392b58d6f0, a benign ChatGPT email, was hallucinated into a fake
// "account suspended" alert). Requires "Return Intermediate Steps" enabled
// on the Fetch Emails Agent node.
var steps = first.intermediateSteps || [];
for (var s = 0; s < steps.length; s++) {
  var obs = typeof steps[s].observation === 'string' ? steps[s].observation : '';
  if (obs.charAt(0) === '[') {
    try {
      var content = JSON.parse(obs);
      if (Array.isArray(content)) {
        obs = content.map(function(p) { return (p && typeof p.text === 'string') ? p.text : ''; }).join('\n\n');
      }
    } catch(e) {}
  }
  if (/^ID:\s*\S+/m.test(obs)) {
    emails = parseRawObservation(obs);
    source = 'mcp_raw';
    break;
  }
}

var mcpMatches = emails.length;

// Fallback: no usable tool observation captured (e.g. older n8n agent version,
// or the option got reverted) -- fall back to parsing the agent's own output
// like before, so one bad run doesn't blank out the whole cron cycle.
if (emails.length === 0) {
  var raw = (first.output || '').trim();
  mcpMatches = (raw.match(/"id"\s*:/g) || []).length;

  var arrayMatches = raw.match(/\[[\s\S]*?\]/g) || [];
  for (var a = 0; a < arrayMatches.length; a++) {
    try {
      var parsed = JSON.parse(arrayMatches[a]);
      if (Array.isArray(parsed) && parsed.length > 0 && parsed[0].id) { emails = parsed; source = 'agent_json_fallback'; break; }
    } catch(e) {}
  }

  if (emails.length === 0 && mcpMatches > 0) {
    try {
      var objRe = /\{(?:[^{}]|\{[^{}]*\})*"id"\s*:\s*"[^"]+"(?:[^{}]|\{[^{}]*\})*\}/g;
      var objMatches = raw.match(objRe) || [];
      var parsedObjs = objMatches.map(function(m) { try { return JSON.parse(m); } catch(e) { return null; } }).filter(function(o) { return o && o.id && o.from_email; });
      if (parsedObjs.length > 0) { emails = parsedObjs; source = 'agent_json_fallback'; }
    } catch(e) {}
  }
}

var agentCount = emails.filter(function(e) { return e.id; }).length;

var fs = require('fs');
var sigPath = '/memory/email_signals.json';
var store = { signals: [], pending: {}, seen_ids: [], metrics: [] };
try { store = JSON.parse(fs.readFileSync(sigPath, 'utf8')); } catch(e) {}
store.metrics = store.metrics || [];
var metric = { ts: new Date().toISOString(), mcp_count: mcpMatches, agent_count: agentCount, source: source };
if (source === 'agent_json_fallback' && agentCount === 0 && mcpMatches > 0) metric.error = 'mcp_agent_mismatch';
store.metrics.push(metric);
store.metrics = store.metrics.slice(-100);
fs.writeFileSync(sigPath, JSON.stringify(store, null, 2));

if (emails.length === 0) return [];

var seenIds = new Set(store.seen_ids || []);
var pendingIds = new Set(Object.keys(store.pending || {}));
var classifiedSenders = new Set((store.signals || []).filter(function(s) { return s.label === 'noise'; }).map(function(s) { return s.from_email; }));

var newEmails = emails.filter(function(e) {
  return e.id &&
    !seenIds.has(e.id) &&
    !pendingIds.has(e.id) &&
    !classifiedSenders.has(e.from_email);
});

if (newEmails.length === 0) return [];
return newEmails.slice(0, 5).map(function(e) { return { json: e }; });

function _post(hostname, port, path, body) {
  return new Promise(function(resolve, reject) {
    var http = require('http');
    var payload = JSON.stringify(body);
    var byteLen = Buffer.byteLength(payload, 'utf8');
    var req = http.request(
      { hostname: hostname, port: port, path: path, method: 'POST',
        headers: {'Content-Type':'application/json','Content-Length':byteLen} },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end', function() {
          try { resolve(JSON.parse(data)); } catch(e) { resolve({}); }
        });
      }
    );
    req.on('error', reject);
    req.write(payload); req.end();
  });
}

var fs = require('fs');
var sigPath = '/memory/email_signals.json';
var store = { signals: [], pending: {}, seen_ids: [] };
try { store = JSON.parse(fs.readFileSync(sigPath, 'utf8')); } catch(e) {}
var signals = store.signals || [];

var triagePrompt = [
  'Classify this email. Return JSON only.',
  '',
  'SKIP (return {"skip": true}) ONLY for:',
  '- Mass newsletters or mailing list digests',
  '- Pure marketing or promotional offers',
  '- Social media activity notifications (LinkedIn updates, Twitter likes, etc.)',
  '',
  'KEEP (return {"skip": false}) for EVERYTHING ELSE, including:',
  '- Personal emails from real people',
  '- Financial/banking alerts, trade confirmations, account notifications',
  '- Invoices, receipts, order confirmations',
  '- Security alerts, login notifications',
  '- Business correspondence',
  '- Support or service emails requiring attention',
  '',
  'Return ONLY this JSON:',
  '{"skip": true, "reason": "newsletter|marketing|social"}',
  'or',
  '{"skip": false, "reason": "genuine|financial|transactional|personal|business"}'
].join('\n');

var results = [];

for (var email of $input.all().map(i => i.json)) {
  var userMsg = 'From: ' + email.from_name + ' <' + email.from_email + '>\nSubject: ' + email.subject + '\nPreview: ' + (email.snippet || '');

  var triageResp = await _post('host.docker.internal', 11434, '/api/chat', {
    model: 'qwen3:14b',
    messages: [{ role: 'system', content: triagePrompt }, { role: 'user', content: userMsg }],
    stream: false, think: false,
    options: { temperature: 0.1 }
  });
  var triageContent = triageResp.message?.content || '';
  var triage = { skip: false, reason: 'parse_error' };
  try {
    var m = triageContent.match(/\{[^}]+\}/);
    if (m) triage = JSON.parse(m[0]);
  } catch(e) {}
  if (triage.reason === 'genuine') triage.skip = false;

  if (triage.skip) continue;

  var sigCtx = signals.length > 0
    ? signals.slice(-15).map(s => '- ' + s.from_email + ' \u2192 ' + s.label + ' (' + (s.last_subject || '') + ')').join('\n')
    : 'No signals yet.';

  var scorePrompt = 'Score this email\'s interrupt-worthiness 1-10 for a busy professional.\n\nPast user feedback:\n' + sigCtx + '\n\nEmail:\nFrom: ' + email.from_name + ' <' + email.from_email + '>\nSubject: ' + email.subject + '\nPreview: ' + (email.snippet || '') + '\n\nRules: 9-10 = urgent/time-sensitive. 7-8 = worth reading soon. 1-6 = can wait.\nReturn JSON only: {"score": N, "reason": "one sentence"}';

  var scoreResp = await _post('host.docker.internal', 11434, '/api/chat', {
    model: 'qwen3:14b',
    messages: [{ role: 'user', content: scorePrompt }],
    stream: false, think: false,
    options: { temperature: 0.2 }
  });
  var scoreContent = scoreResp.message?.content || '';
  var scoring = { score: 5, reason: 'could not parse' };
  try {
    var sm = scoreContent.match(/\{[^}]+\}/);
    if (sm) scoring = JSON.parse(sm[0]);
  } catch(e) {}
  var score = Number(scoring.score) || 5;

  // Mark as notified and save to pending
  store.seen_ids = store.seen_ids || [];
  if (!store.seen_ids.includes(email.id)) store.seen_ids.push(email.id);
  store.seen_ids = store.seen_ids.slice(-600);
  store.pending[email.id] = { from_email: email.from_email, from_name: email.from_name, subject: email.subject, score };

  results.push({ json: Object.assign({}, email, { score: score, score_reason: scoring.reason, triage_reason: triage.reason }) });
}

var pkeys = Object.keys(store.pending);
if (pkeys.length > 50) delete store.pending[pkeys[0]];
fs.writeFileSync(sigPath, JSON.stringify(store, null, 2));

return results;
